// node mascot/build.mjs → components/prue.tsx (core.ts + the React wrapper in component.tsx.txt)
import fs from "fs";

const here = (f) => new URL(f, import.meta.url);
const core = fs.readFileSync(here("core.ts"), "utf8");
const comp = fs.readFileSync(here("component.tsx.txt"), "utf8");
fs.writeFileSync(
  here("../components/prue.tsx"),
  "// GENERATED by mascot/build.mjs from mascot/core.ts. Edit there.\n" + core.replace(/^\/\/ Prue v3.*\n\/\/ Single source.*\n/, "") + comp,
);
console.log("built components/prue.tsx");
